"""Report offline observability and separately recorded contact-wrench validation."""
from pathlib import Path
import datetime,json,hashlib,shutil,html
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
D=Path('/data/humanoid-sitting-perception/low_seat_contact_01');O=D/'progress_report_265'
def read(p):return json.loads(Path(p).read_text())
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def table(headers,rows):return '<table><tr>'+''.join('<th>'+html.escape(str(h))+'</th>' for h in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+html.escape(str(c))+'</td>' for c in row)+'</tr>' for row in rows)+'</table>'
def main():
 O.mkdir(exist_ok=False);s=read(D/'spatial_wrench_diagnosis_v2_255/results.json');a=read(D/'spatial_wrench_audit_v2_256/independent_audit.json');c=read(D/'contact_wrench_audit_260/independent_audit.json');v=read(D/'all_attempts_video_audit_263/independent_audit.json');r=read(D/'contact_wrench_diagnosis_261/results.json')
 assert a['passed'] and c['exact_prefix_replay'] and v['passed'];sel=[x for x in r['summaries'] if x['case'] in [0,1]]
 fig,axs=plt.subplots(2,2,figsize=(12,7))
 for j,case in enumerate([0,1]):
  for i,side in enumerate(['left','right']):
   rr=[x for x in r['rows'] if x['case']==case and x['side']==side and x['available']];tt=[x['t'] for x in rr];axs[i,j].plot(tt,[x['estimated'][3] for x in rr],label='quasi-static estimate');axs[i,j].plot(tt,[x['contact_wrench'][3] for x in rr],label='summed contact label');axs[i,j].set_title(f'Case {case}, {side}');axs[i,j].set_ylabel('Roll moment about ankle origin (Nm)');axs[i,j].set_xlabel('Time (s)');axs[i,j].legend();axs[i,j].grid(alpha=.2)
 fig.suptitle('Contact moment validation; labels never feed control\nPhysical repair remains unresolved');fig.tight_layout();fig.savefig(O/'roll_moments.png',dpi=150);plt.close(fig)
 fig,ax=plt.subplots(1,2,figsize=(12,4));x=np.arange(24)
 for side in ['left','right']:
  rr=sorted([z for z in r['summaries'] if z['side']==side],key=lambda z:z['case']);ss=sorted([z for z in s['summaries'] if z['side']==side],key=lambda z:z['case']);ax[0].plot(x,[z['error_rms'][3] for z in rr],'.-',label=side);ax[1].plot(x,[z['condition_scaled_max'] for z in ss],'.-',label=side)
 ax[0].set_ylabel('Roll-moment RMS error (Nm)');ax[1].set_ylabel('Scaled matrix condition (0.1 m)')
 for aa in ax:aa.set_xlabel('Development case');aa.legend();aa.grid(alpha=.2)
 fig.suptitle('All 24 cases, 11–12.9 s; includes failures and unsupported hovering');fig.tight_layout();fig.savefig(O/'conditioning_and_error.png',dpi=150);plt.close(fig)
 inputs=[D/'spatial_wrench_diagnosis_v2_255/results.json',D/'spatial_wrench_audit_v2_256/independent_audit.json',D/'spatial_contact_mapping_recovery_255/recovery.json',D/'contact_recorder_preparation_258/results.json',D/'contact_wrench_audit_260/independent_audit.json',D/'contact_wrench_diagnosis_261/results.json',D/'all_attempts_video_audit_263/independent_audit.json',D/'contact_wrench_revision_259.json']
 for i,p in enumerate(inputs):shutil.copy2(p,O/f'{i+1:02}_{p.parent.name}_{p.name}')
 gates=table(['Check','Result'],[['Offline six-joint geometry/virtual-work audit',a['passed']],['New 24-case 13 s exact global replay',c['exact_prefix_replay']],['Existing contact-return validation',c['contact_return_checks']['passed']],['No extra contact queries',c['contact_return_checks']['extra_queries']==0],['New full20s / optimizer / holdout trials',0],['Physical repair / PPO admission',False]])
 selected=table(['Case / foot','Estimated median Mx (Nm)','Contact median Mx (Nm)','Mx RMS error (Nm)','Normal / friction median Mx (Nm)'],[[f"{z['case']} / {z['side']}",f"{z['estimated_median'][3]:.6f}",f"{z['truth_median'][3]:.6f}",f"{z['error_rms'][3]:.6f}",f"{z['normal_moment_median'][0]:.6f} / {z['friction_moment_median'][0]:.6f}"] for z in sel])
 allrows=table(['Case / side','Samples','Force RMS error x/y/z (N)','Moment RMS error x/y/z (Nm)'],[[f"{z['case']} / {z['side']}",z['samples'],', '.join(f'{x:.3f}' for x in z['error_rms'][:3]),', '.join(f'{x:.3f}' for x in z['error_rms'][3:])] for z in r['summaries']])
 text=f'''<!doctype html><html><head><meta charset="utf-8"><title>Low-seat repair: spatial contact diagnosis</title><style>body{{font:17px/1.5 system-ui;background:#eef3f6;color:#223642;margin:0}}main{{max-width:1160px;margin:auto;background:white;padding:32px}}h1,h2{{line-height:1.2}}.status{{background:#fff1d6;border-left:6px solid #9b681d;padding:18px}}table{{border-collapse:collapse;width:100%;margin:18px 0;font-size:14px}}th,td{{padding:9px;border-bottom:1px solid #ccd5da;text-align:left}}th{{background:#e8eef2}}img,video{{width:100%;height:auto}}small{{color:#546b78}}</style></head><body><main><h1>Spatial contact diagnosis</h1><p class="status"><b>Physical repair remains unresolved.</b> Best verified controller: 64/72 clean, 70 stable, 8 slipping and 2 housing-contact cases. The 64 successes remain protected. No new full 20-second repair test, retention run, PPO, fresh holdout or promotion.</p><h2>Scope and checks</h2><p>Offline255 estimates a six-component foot wrench from saved encoders, IMU gravity, approximate PD torque and frozen kinematics/inertia. All 2,400 records passed independent finite-difference work checks. A 1 Nm error in each joint torque can change selected roll estimates by about 1.01 Nm; this is unit sensitivity, not an established error bound. Model conditioning alone does not certify feedback.</p><p>Diagnostic259 runs one unchanged centered234 13-second prefix across 24 environments: 15,600 active environment ticks plus 600 initial settling, zero full20s episodes or optimizer steps. It intercepts existing normal/friction query returns, immediately copying separate application points and count buffers before reuse. No extra query, sensor substitution or use of contact truth in control. Individual contact moments are summed about each ankle-link origin; average contact position is not treated as a center of pressure.</p>{gates}<h2>Selected roll moments, 11–12.9 seconds</h2><p class="status"><b>The proposed quasi-static roll-moment feedback is not admitted.</b> Selected estimates are +0.883 to +0.956 Nm, but individually summed contact medians are −0.034 to −0.027 Nm. RMS errors are 0.913–0.986 Nm. The estimate has the wrong sign and is much larger than the contact moment. Do not treat it as a realized roll imbalance to correct. This is not proof of a single source of error or impossibility of other approaches.</p>{selected}<img src="roll_moments.png" alt="Estimated and independently summed contact roll moments"><p>Summed simulator contacts are diagnostic labels. Quasi-static estimates omit dynamic generalized forces, other contacts and the gap between approximate implicit-PD telemetry and actual solver drive effort. Neither arithmetic agreement nor a stable hover establishes seated support. Raw velocity settling, pitch/gyro/current-geometry guards, materials and physical criteria remain unchanged.</p><h2>All cases retained</h2><img src="conditioning_and_error.png" alt="All-case roll moment error and conditioning">{allrows}<h2>Preserved correction</h2><p>Original255 used actuator body order for an auxiliary other-leg-contact label. V2 uses saved contact_body_names, changing 2,390 auxiliary row labels while reusing identical wrench matrices, estimates, force errors and sensitivities. Original files and the unexecuted original audit draft remain preserved. No physics or model calculation rerun; physical outcomes never changed.</p><h2>Complete attempt video</h2><p>58.4 seconds; all 840 full trials (489 clean, 351 failed), 168 recorded diagnostic prefixes and 96 aborted attempts without saved motion explicitly disclosed. These historical repeated counts are not best-controller accuracy. Recorded XYZW link-pose schematic, not camera footage; 0.1-second poses bracket 0.02-second event labels.</p><video controls preload="metadata" src="../all_attempts_video_262/all_attempts.mp4"></video><h2>Remaining work</h2><p>Use the verified contact-moment error and sensitivity to decide whether spatial feedback is justified; do not infer a repaired controller or simply increase gains. Preserve the improved approach balance and unchanged settling contract. The other three difficult geometries still lack validated complete contact transitions. All eight failures must be removed and all64 retained in72 matched full20s tests before PPO. Fresh holdout remains closed.</p><p>No new full-duration effort result. Torque remains approximate implicit-PD telemetry, not direct solver/hardware motor effort, energy or a global optimum. Failed hovering and diagnostic fragments are excluded from effort savings. Reference-assisted simulation and two seeds do not establish unassisted or real-robot sitting; leaning has not broadened.</p><small>Interim development diagnosis; task unfinished. All previous failed experiments remain preserved.</small></main></body></html>'''
 (O/'findings.html').write_text(text);(O/'summary.json').write_text(json.dumps(dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),physical_admission=False,selected=sel,exact_prefix=c['exact_prefix_replay'],contact_checks=c['contact_return_checks'],video=dict(full=v['full_trials'],prefix=v['recorded_prefixes'],events=v['event_frames_checked'])),indent=2));(O/'SHA256.json').write_text(json.dumps({p.name:sha(p) for p in O.iterdir() if p.is_file()},indent=2));print('REPORT265_COMPLETE')
if __name__=='__main__':main()
